def _q(sv, q):
    k = int(q * (len(sv) - 1))
    if k < 0:
        k = 0
    if k >= len(sv):
        k = len(sv) - 1
    return sv[k]


def family_init(ctx):
    b = ctx.bars
    n = len(b)
    h = [float(x["h"]) for x in b]
    l = [float(x["l"]) for x in b]
    c = [float(x["c"]) for x in b]
    v = [float(x.get("v") or 0.0) for x in b]
    ts = [str(x["t"]) for x in b]

    vq = float(ctx.p.vol_pct)
    rq = float(ctx.p.rng_pct)
    RN = int(ctx.p.rng_n)
    EX = int(ctx.p.ext_n)
    SS = int(ctx.p.slot_sess)
    MINS = int(ctx.p.min_slot)
    WIN = int(ctx.p.win)

    slot = [t[11:16] for t in ts]
    rng = [h[j] - l[j] for j in range(n)]

    hist = {}
    ent = [0] * n
    pend = None
    for j in range(n):
        # ---- effort: is this bar's volume extreme for THIS time of day?
        s = slot[j]
        prior = hist.get(s)
        hot = False
        if prior is not None and len(prior) >= MINS:
            w = sorted(prior[-SS:])
            hot = v[j] >= _q(w, vq)
        if prior is None:
            hist[s] = [v[j]]
        else:
            prior.append(v[j])

        churn = 0
        if hot and j >= RN and j >= EX:
            # ---- result: and yet the bar went nowhere
            wr = sorted(rng[j - RN:j])
            if rng[j] <= _q(wr, rq):
                hh = max(h[j - EX + 1:j + 1])
                ll = min(l[j - EX + 1:j + 1])
                if h[j] >= hh:
                    churn = -1          # absorbed at the highs -> short setup
                elif l[j] <= ll:
                    churn = 1           # absorbed at the lows  -> long setup

        if churn:
            pend = {"d": churn, "hi": h[j], "lo": l[j], "j": j}
            continue
        if pend is None:
            continue
        if j - pend["j"] > WIN:
            pend = None
            continue
        # ---- the trade is the FAILURE: price closes clean through the bar
        if pend["d"] < 0 and c[j] < pend["lo"]:
            ent[j] = -1
            pend = None
        elif pend["d"] > 0 and c[j] > pend["hi"]:
            ent[j] = 1
            pend = None
    ctx.ent = ctx.series(ent, "entry")


def signal(ctx, i):
    e = ctx.ent[i]
    return 0 if e is None else int(e)
